 * @brief Calculates the length of a null-terminated string without using strlen.
 * 
 * @param str The string to measure.
 * @return size_t The length of the string (number of characters before the null terminator).
 */
size_t my_strlen(const char *str) {
    size_t length = 0;

    // Loop until the current character is the null terminator ('\0')
